    q1: ['python', 'javascript', 'ruby'],
    q2: ['lisp', 'csharp', 'haskell'],
    q3: ['php', 'typescript', 'golang']
};

const quizForm = document.getElementById('quizForm');
const resultsDiv = document.getElementById('results');
const resultsContent = document.getElementById('resultsContent');

quizForm.addEventListener('submit', function(e) {
    e.preventDefault();
    calculateResults();
});

function calculateResults() {
    let totalScore = 0;
    const maxScore = 3;
    const resultDetails = [];

    for (let questionNum = 1; questionNum <= 3; questionNum++) {
        const questionKey = `q${questionNum}`;
        const selectedAnswers = Array.from(
            document.querySelectorAll(`input[name="${questionKey}"]:checked`)
        ).map(input => input.value);

        const correct = correctAnswers[questionKey];
        const isCorrect = arraysEqual(selectedAnswers.sort(), correct.sort());

        if (isCorrect) {
            totalScore++;
        }

        resultDetails.push({
            question: questionNum,
            selected: selectedAnswers.length > 0 ? selectedAnswers.join(', ') : 'None selected',
            correct: correct.join(', '),
            isCorrect: isCorrect
        });
    }

    displayResults(totalScore, maxScore, resultDetails);
}

function arraysEqual(a, b) {
    if (a.length !== b.length) return false;
    return a.every((val, i) => val === b[i]);
}

function displayResults(score, maxScore, details) {
    let html = `<div class="result-score">Your Score: ${score} out of ${maxScore}</div><br>`;

    details.forEach(detail => {
        const status = detail.isCorrect ? '✓ Correct' : '✗ Incorrect';
        const statusColor = detail.isCorrect ? 'color: #4ade80;' : 'color: #ff6b6b;';
        html += `
            <div class="result-item">
                <strong>Question ${detail.question}:</strong> <span style="${statusColor}">${status}</span><br>
                <small>Your answer: ${detail.selected}</small><br>
                <small>Correct answer: ${detail.correct}</small>
            </div>
        `;
    });

    resultsContent.innerHTML = html;
    resultsDiv.classList.remove('hidden');
    quizForm.style.display = 'none';
}

function resetQuiz() {
    quizForm.reset();
    resultsDiv.classList.add('hidden');
    quizForm.style.display = 'block';
    resultsContent.innerHTML = '';
}
